use std::error::Error;
use std::fmt::Write as _;
use std::io::{self, Write};
use std::{env, fs};

use wgpu::util::DeviceExt;

const SHADER: &str = r#"
struct Params {
    width: u32,
    height: u32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let w = params.width;
    let h = params.height;
    let x = id.x;
    let y = id.y;
    if (x >= w || y >= h) {
        return;
    }

    // Edge cells stand in for their missing neighbour.
    let xl = select(x - 1u, x, x == 0u);
    let xr = select(x + 1u, x, x + 1u >= w);
    let yu = select(y - 1u, y, y == 0u);
    let yd = select(y + 1u, y, y + 1u >= h);

    let row = y * w;
    let centre = src[row + x];
    let left = src[row + xl];
    let right = src[row + xr];
    let up = src[yu * w + x];
    let down = src[yd * w + x];

    dst[row + x] = (4u * centre + left + right + up + down) / 8u;
}
"#;

const MAX_DIM: u32 = 512;
const MAX_STEPS: u32 = 1000;
const MAX_VALUE: u32 = 1_000_000;

struct Grid {
    width: u32,
    height: u32,
    steps: u32,
    cells: Vec<u32>,
}

fn parse_input(text: &str) -> Result<Grid, Box<dyn Error>> {
    let mut tokens = text.split_whitespace();
    let mut next = |what: &str| -> Result<u32, Box<dyn Error>> {
        let token = tokens.next().ok_or_else(|| format!("missing {what}"))?;
        Ok(token.parse::<u32>().map_err(|e| format!("bad {what} {token:?}: {e}"))?)
    };

    let width = next("width")?;
    let height = next("height")?;
    let steps = next("steps")?;
    if !(1..=MAX_DIM).contains(&width) || !(1..=MAX_DIM).contains(&height) {
        return Err(format!("grid size {width}x{height} out of range").into());
    }
    if steps > MAX_STEPS {
        return Err(format!("steps {steps} out of range").into());
    }

    let count = width as usize * height as usize;
    let mut cells = Vec::with_capacity(count);
    for _ in 0..count {
        let value = next("cell")?;
        if value > MAX_VALUE {
            return Err(format!("cell value {value} out of range").into());
        }
        cells.push(value);
    }
    if tokens.next().is_some() {
        return Err("trailing data after grid".into());
    }

    Ok(Grid { width, height, steps, cells })
}

fn run_steps(grid: &Grid) -> Result<Vec<u32>, Box<dyn Error>> {
    let instance = wgpu::Instance::default();
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
        power_preference: wgpu::PowerPreference::HighPerformance,
        ..Default::default()
    }))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))?;

    let size = (grid.cells.len() * std::mem::size_of::<u32>()) as u64;
    let storage_usage = wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST;
    // Two buffers swapped each step, so a step never reads cells it has already written.
    let buffers = [0, 1].map(|i| {
        device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some(if i == 0 { "grid a" } else { "grid b" }),
            contents: bytemuck_cast(&grid.cells),
            usage: storage_usage,
        })
    });

    let params = [grid.width.to_le_bytes(), grid.height.to_le_bytes(), [0; 4], [0; 4]].concat();
    let params_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: &params,
        usage: wgpu::BufferUsages::UNIFORM,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("heat"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("heat"),
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let layout = pipeline.get_bind_group_layout(0);

    // bind_groups[i] reads buffers[i] and writes buffers[1 - i].
    let bind_groups = [0, 1].map(|i| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: &layout,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: params_buffer.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 1, resource: buffers[i].as_entire_binding() },
                wgpu::BindGroupEntry { binding: 2, resource: buffers[1 - i].as_entire_binding() },
            ],
        })
    });

    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
    let groups_x = grid.width.div_ceil(16);
    let groups_y = grid.height.div_ceil(16);
    for step in 0..grid.steps as usize {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: Some("heat step"),
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_groups[step % 2], &[]);
        pass.dispatch_workgroups(groups_x, groups_y, 1);
    }

    // After `steps` swaps, the latest values sit in buffers[steps % 2].
    let result = &buffers[grid.steps as usize % 2];
    let staging = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    encoder.copy_buffer_to_buffer(result, 0, &staging, 0, size);
    queue.submit(Some(encoder.finish()));

    let (sender, receiver) = std::sync::mpsc::channel();
    staging.slice(..).map_async(wgpu::MapMode::Read, move |r| {
        let _ = sender.send(r);
    });
    device.poll(wgpu::PollType::wait_indefinitely())?;
    receiver.recv()??;

    let data = staging.slice(..).get_mapped_range();
    let cells = data
        .chunks_exact(4)
        .map(|chunk| u32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]))
        .collect();
    drop(data);
    staging.unmap();
    Ok(cells)
}

fn bytemuck_cast(values: &[u32]) -> &[u8] {
    // SAFETY: u32 has no padding and any bit pattern is a valid byte sequence.
    unsafe { std::slice::from_raw_parts(values.as_ptr().cast::<u8>(), std::mem::size_of_val(values)) }
}

fn main() -> Result<(), Box<dyn Error>> {
    let path = env::args().nth(1).ok_or("usage: heat <input-file>")?;
    let text = fs::read_to_string(&path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let mut grid = parse_input(&text)?;

    if grid.steps > 0 {
        grid.cells = run_steps(&grid)?;
    }

    let mut out = String::with_capacity(grid.cells.len() * 8);
    let mut sum: u64 = 0;
    for row in grid.cells.chunks_exact(grid.width as usize) {
        for (i, value) in row.iter().enumerate() {
            if i > 0 {
                out.push(' ');
            }
            write!(out, "{value}")?;
            sum += u64::from(*value);
        }
        out.push('\n');
    }
    for value in &grid.cells[..0] {
        sum += u64::from(*value);
    }
    writeln!(out, "SUM {sum}")?;

    let mut stdout = io::stdout().lock();
    stdout.write_all(out.as_bytes())?;
    stdout.flush()?;
    Ok(())
}

