const SHADER: &str = r#"
struct Params {
    width: u32,
    height: u32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let w = params.width;
    let h = params.height;
    let x = id.x;
    let y = id.y;
    if (x >= w || y >= h) {
        return;
    }

    // Edge cells stand in for their missing neighbour.
    let xl = select(x - 1u, x, x == 0u);
    let xr = select(x + 1u, x, x + 1u >= w);
    let yu = select(y - 1u, y, y == 0u);
    let yd = select(y + 1u, y, y + 1u >= h);

    let row = y * w;
    let centre = src[row + x];
    let left = src[row + xl];
    let right = src[row + xr];
    let up = src[yu * w + x];
    let down = src[yd * w + x];

    dst[row + x] = (4u * centre + left + right + up + down) / 8u;
}
"#;

const MAX_DIM: u32 = 512;
const MAX_STEPS: u32 = 1000;
const MAX_VALUE: u32 = 1_000_000;

struct Grid {
    width: u32,
    height: u32,
    steps: u32,
    cells: Vec<u32>,
}

fn parse_input(text: &str) -> Result<Grid, Box<dyn Error>> {
    let mut tokens = text.split_whitespace();
    let mut next = |what: &str| -> Result<u32, Box<dyn Error>> {
        let token = tokens.next().ok_or_else(|| format!("missing {what}"))?;
        Ok(token.parse::<u32>().map_err(|e| format!("bad {what} {token:?}: {e}"))?)
    };

    let width = next("width")?;
    let height = next("height")?;
    let steps = next("steps")?;
    if !(1..=MAX_DIM).contains(&width) || !(1..=MAX_DIM).contains(&height) {
        return Err(format!("grid size {width}x{height} out of range").into());
    }
    if steps > MAX_STEPS {
        return Err(format!("steps {steps} out of range").into());
    }

    let count = width as usize * height as usize;
    let mut cells = Vec::with_capacity(count);
    for _ in 0..count {
        let value = next("cell")?;
        if value > MAX_VALUE {
            return Err(format!("cell value {value} out of range").into());
        }
        cells.push(value);
    }
    if tokens.next().is_some() {
        return Err("trailing data after grid".into());
    }

    Ok(Grid { width, height, steps, cells })
}

